"""Execute CLI cases; all output and traces are generated by the program."""
import argparse
import json
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path
from uuid import uuid4

ROOT = Path(__file__).resolve().parents[1]


def write(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--output-root", type=Path, default=ROOT / "runtime" / "example-batches" / uuid4().hex)
    args = parser.parse_args()
    base = args.output_root.resolve()
    base.mkdir(parents=True, exist_ok=False)
    batch_id = uuid4().hex
    db = ROOT / "runtime" / ("examples-" + batch_id + ".sqlite3")
    common = dict(theme="校园毕业季", budget=12, deadline="2026-11-01T18:00:00+08:00")
    cases = [
        ("normal", "normal", {}, [], 0),
        ("budget-adjust", "budget-adjust", {"budget": 10}, [], 0),
        ("missing-budget", "missing-budget", {"budget": None}, [], 2),
        ("missing-deadline", "missing-deadline", {"deadline": None}, [], 2),
        ("tool-failure", "tool-failure", {}, ["--fail-once", "generate_script"], 0),
        ("no-feasible-budget", "no-feasible-budget", {"budget": 5}, [], 3),
        ("no-feasible-time", "no-feasible-time", {"deadline": "2026-11-01T12:30:00+08:00"}, [], 3),
        ("partial-script", "partial-script", {}, ["--partial-once", "generate_script"], 0),
        ("empty-materials", "empty-materials", {"theme": "不存在的主题"}, [], 3),
        ("step-limit", "step-limit", {}, ["--max-rounds", "1"], 3),
        ("replay", "normal", {}, [], 0),
        ("conflict", "normal", {"budget": 99}, [], 5),
    ]
    summary = []
    for name, task_id, changes, extra, expected in cases:
        raw = {"task_id": "campus-" + task_id, **common, **changes}
        raw = {k: v for k, v in raw.items() if v is not None}
        source = base / "inputs" / (name + ".json")
        write(source, raw)
        command = [sys.executable, "-X", "utf8", str(ROOT / "run.py"), "--input", str(source), "--mode", "mock",
                   "--now", "2026-11-01T12:00:00+08:00", "--db", str(db), "--output-dir", str(base / name)] + extra
        completed = subprocess.run(command, cwd=ROOT, capture_output=True, text=True, encoding="utf-8")
        (base / name / "stdout.json").write_text(completed.stdout, encoding="utf-8")
        (base / name / "stderr.txt").write_text(completed.stderr, encoding="utf-8")
        out = json.loads((base / name / "output.json").read_text(encoding="utf-8"))
        events = [json.loads(line) for line in (base / name / "trace.jsonl").read_text(encoding="utf-8").splitlines()]
        summary.append(dict(case=name, exit_code=completed.returncode, expected_exit_code=expected,
                            status=out["status"], mode=out["mode"], replayed=out["replayed"],
                            estimated_total_cost=out["result"]["estimated_total_cost"],
                            retained_tool_results=len(out["result"]["tool_results"]),
                            new_tool_calls=sum(e["event_type"] == "tool_result" for e in events), trace=str(base / name / "trace.jsonl")))
        if completed.returncode != expected:
            raise RuntimeError("Unexpected case result: " + name)
    write(base / "summary.json", {"generated_at": datetime.now(timezone.utc).isoformat(), "mode": "mock", "cases": summary,
                                  "boundary": "规则 Mock 的实际执行，不证明真实模型重规划"})
    print(json.dumps(summary, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
